"""Writes docs/REPORT_FACTS.md from the measured JSON files (experiments/plantdoc/*.json, docs/metrics/*.json). Re-run after any experiment."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
EXP = ROOT / "experiments" / "plantdoc"
M = json.loads((EXP / "metrics.json").read_text())
LAT = json.loads((EXP / "latency.json").read_text())
EDGE = json.loads((ROOT / "docs" / "metrics" / "edge_tests.json").read_text())
H, C, CS, CT, MB, BL = M["heuristic"], M["cnn"], M["cnn_shipped_protocol"], M["cnn_tuned"], M["mobilenet"], M["baseline"]


def pm(b, k, d=1, pct=True):
    x = b[k]
    s = 100 if pct else 1
    return f"{x['mean'] * s:.{d}f} ± {x['std'] * s:.{d}f}" + (" %" if pct else "")


def p(x, d=1):
    return f"{x * 100:.{d}f} %"


def one(b, k, d=1):
    return f"{b[k]['mean'] * 100:.{d}f} %"


tch, tg = H["test_crop_hint"], H["test_general"]
lines = []
w = lines.append
w("# REPORT FACTS - AgriVision (CSE-C-C16)\n")
w("Generated by `scripts/make_report_facts.py` from `experiments/plantdoc/*.json` and `docs/metrics/*.json`. Every document must agree with this file.\n")
w("## 1. Identity\n")
w("- Project: **AI Powered Crop Disease Detection and Recommendation System for Sustainable Development**; product name **AgriVision**; batch CSE-C-C16 (Batch C16, CSE-C).")
w("- Students: Pishke Vishal 23K91A05J2; Kyatham Nithisha 23K91A05D1; Mekala Tharun Kuruma 23K91A05F1; Nakka Sreenith 23K91A05H0. Guide: V Krishna Teja. College, HOD, principal, designation, academic year: bracketed placeholders (unknown).")
w("- Base paper (batch documents): Pakka, Wilkerson, Chen, Tzeng, *Foliagen: Framework for Crop Foliage Image Generation from Individual Leaf Images*, IEEE Access, 2026, DOI 10.1109/ACCESS.2026.3727421 (PDF in `Documentary/`). It is an image-generation framework, not a classifier or a recommender.")
w("- Companion classification paper (also in the repo as `BASEPAPER_*.pdf`, arXiv 2604.11332): Sherifi et al., *PD36-C*, 1,250,694 parameters, 4.77 MB, 99.53 % test accuracy on the New Plant Diseases Dataset (87k images, 38 classes). The product's knowledge base uses its 38-class label set and `train.py` calls its network 'PD36-C-style'; the trained net here is NOT PD36-C (189,655 parameters).")
w("- Supporting paper: arXiv 2505.00741 (LSTM + CNN multi-crop leaves, 70,295 training images, 38 classes, 99.1 % train / 96.4 % validation as recorded in `archived_base_papers/BASEPAPER_REFERENCES.md`).\n")
w("## 2. What was built (and what was not)\n")
w("- Web platform: React 18 + Vite 8 + TypeScript 5.9 + Tailwind 4 SPA (12 page components, `frontend/src`, 5,647 lines of TS/TSX), FastAPI layer `backend/main.py` (437 lines, 16 routes) over the original Flask product `agrivision/` (app.py 398, disease_db.py 221, inference.py 177, train.py 103 lines), one SQLite file (`users`, `results`). Ports 8416 / 5416, demo login `demo@agrivision.ai` / `demo1234`.")
w("- **Diagnosis engine in the product = colour/texture heuristic** (`agrivision/inference.py`): 256x256 resize, share of green / brown / yellow / dark / white pixels and global std, hand-set score per class, a hash-seeded jitter, confidence mapped into 0.62-0.99 (never low). `agrivision/models/` is empty so no trained network is loaded; the UI says 'Heuristic engine' on every result.")
w("- Knowledge base: 38 classes (14 crops: apple, blueberry, cherry, corn, grape, orange, peach, bell pepper, potato, raspberry, soybean, squash, strawberry, tomato; 12 healthy, 26 diseased), 26 diseases with curated symptoms/treatment/prevention, severity: 12 high / 14 medium / 12 none; per disease 3 treatments (chemical, organic, cultural) + prevention + lifecycle + cost text in rupees. Kinds: fungal 19, healthy 12, viral 3, bacterial 3, pest 1.")
w("- Multilingual: English / Hindi / Marathi **interface strings only** (44 keys in `frontend/src/lib/i18n.tsx`); disease and treatment text stays English.")
w("- **Not implemented** although the abstract lists them: yield prediction, weather-based recommendations (OpenWeatherMap), fertiliser-dose recommender (only treatment text), voice interface, administrative dashboard, a CNN in the product, expert validation of the advice. The dashboard 'season alert' is a fixed sentence.\n")
w("## 3. Dataset (PlantDoc, measured)\n")
d = M["dataset"]
w(f"- Source: PlantDoc (Singh et al., CoDS-COMAD 2020), CC-BY-4.0, HF mirror `geraldmc/plantdoc-full`; local copy `datasets/plantdoc-images` (git-ignored, 445 MB). Web-scraped field photos, 13 crops.")
w(f"- Local folder layout: **{d['n_train']:,} train + {d['n_test']} test = {d['n_train'] + d['n_test']:,} images, 28 class folders in train, 27 in test** (`Tomato_two_spotted_spider_mites_leaf` has 2 train images and no test image). Test macro scores are therefore over 27 classes. Largest test class Corn_leaf_blight 12 (5.1 %).")
w("- Class sizes (train): 2 to 180 images per class (Corn_leaf_blight 180, Tomato_Septoria 140, Squash_Powdery 124; Tomato_leaf_mosaic_virus 44, Cherry 47, spider mites 2). 10 healthy folders (Apple, Bell pepper, Blueberry, Cherry, Peach, Raspberry, Soybean, Strawberry, Tomato, Grape): 90 healthy and 146 diseased test images (61.9 % diseased).")
w("- All 28 PlantDoc folders map one-to-one onto the 38 canonical classes (`PLANTDOC_MAP`); 10 canonical classes have no PlantDoc images (Apple black rot, Cherry powdery mildew, Corn healthy, Grape esca, Grape leaf blight, Orange HLB, Peach bacterial spot, Potato healthy, Strawberry leaf scorch, Tomato target spot).")
w("- Original paper's numbers for context (verified from arXiv 1911.10317): 2,598 images, 27 classes; VGG16 on uncropped PlantDoc 13.74-29.73 % depending on pre-training; on cropped leaves 44.5-70.5 % (VGG16, InceptionV3, InceptionResNetV2, 80/20 split, 100x100 px).\n")
w("## 4. Measured results (PlantDoc test split, 236 photos; macro-F1 over the 27 classes present)\n")
w("Everything below is produced by `scripts/run_experiments.py`. Machine: Intel Core i5-12500 (6 cores / 12 threads), 15.7 GB RAM, Windows 11 Pro, CPU only, Python 3.11.9, TensorFlow 2.21.0 (Keras 3), scikit-learn 1.5.0, NumPy, OpenCV 4.11.0, Pillow 12.3.0; other jobs shared the CPU while training, so times are indicative.\n")
w("### 4.1 The engine the app ships (heuristic), 5 `PYTHONHASHSEED` values (0 = what run.bat uses)\n")
w("| Setting | Top-1 | Top-3 | Crop correct | Healthy-vs-diseased | Macro-F1 | Share answered |")
w("|---|---|---|---|---|---|---|")
w(f"| Crop chosen (true crop as hint) | {pm(tch, 'accuracy')} | {pm(tch, 'top3_accuracy')} | {pm(tch, 'crop_accuracy')} | {pm(tch, 'healthy_vs_diseased_accuracy')} | {pm(tch, 'macro_f1', 3, False)} | {100 - tch['failed_share']['mean'] * 100:.1f} % |")
w(f"| Crop left on 'general' | {pm(tg, 'accuracy')} | {pm(tg, 'top3_accuracy')} | {pm(tg, 'crop_accuracy')} | {pm(tg, 'healthy_vs_diseased_accuracy')} | {pm(tg, 'macro_f1', 3, False)} | 100 % |\n")
s0 = H["shipped_hashseed0"]["test_crop_hint"]
w(f"- With hash seed 0 and the crop chosen: top-1 {p(s0['accuracy'])}, top-3 {p(s0['top3_accuracy'])}, macro-F1 {s0['macro_f1']:.3f}. Among photos that got an answer: {pm(tch, 'accuracy_on_answered')}.")
w(f"- Chance: {p(H['chance_with_crop_hint'])} if the crop is known (average of 1/candidates), {p(H['chance_general'])} on 38 classes, majority class {p(H['majority_class_test'])}.")
w(f"- **{p(tch['failed_share']['mean'])} of test photos get no answer when the crop is chosen**: crops with fewer than 3 candidate classes (blueberry, cherry, orange/citrus, peach, bell pepper, raspberry, soybean, squash, strawberry = 10 of the 19 crop options) raise `IndexError` in `_heuristic_predict` and the API returns HTTP 400 `UNREADABLE_IMAGE` for a valid photo.")
w(f"- Healthy leaves recognised as healthy: {pm(tch, 'healthy_recall')} (crop chosen); diseased leaves called diseased: {pm(tch, 'diseased_recall')}. Healthy-vs-diseased accuracy {pm(tch, 'healthy_vs_diseased_accuracy')} is below the 61.9 % obtained by always answering 'diseased'.")
w("- Picture shown by the app (screenshots 08, 09, 10): the demo account holds 10 scans, 8 read 'healthy' at 97.2 %; five of those are PlantDoc photos of diseased leaves (tomato late blight, potato early blight, corn rust, grape black rot, apple scab), so the screens show the engine calling visibly lesioned leaves healthy.")
w("- Reported confidence is not a probability: the three shown scores add up to more than 102 % on 82 % of the 160 test photos the heuristic can answer (max 112 %); mean shown confidence 95 %, yet top-1 is correct on only 21 %, 22 % and 14 % of photos in the 0.80-0.90, 0.90-0.95 and 0.95-1.00 bins; reported latency has a constant +40 ms added in `predict()`.\n")
w("### 4.2 Compact CNN of `agrivision/train.py` (189,655 parameters, 2.4 MB .keras file), trained here\n")
w("Protocol: 224 px, Adam 1e-3, batch 32, in-model augmentation (flip, rotation 0.08, zoom 0.1, contrast 0.1), 10 % stratified validation split carved from the train folder (the shipped script uses the test folder as validation), early stopping on validation accuracy (patience 8), ReduceLROnPlateau, up to 60 epochs, seeds 42/43/44.\n")
w("| Run | Accuracy | Macro-F1 | Top-3 | Crop correct | Healthy-vs-diseased | Epochs | Train time |")
w("|---|---|---|---|---|---|---|---|")
w(f"| CNN, held-out validation (3 seeds) | {pm(C, 'accuracy')} | {pm(C, 'macro_f1', 3, False)} | {pm(C, 'top3_accuracy')} | {pm(C, 'crop_accuracy')} | {pm(C, 'healthy_vs_diseased_accuracy')} | {C['epochs_run']['mean']:.0f} | {C['train_seconds']['mean']:.0f} s |")
w(f"| CNN, shipped protocol (test folder as validation, seed 42) | {one(CS, 'accuracy')} | {CS['macro_f1']['mean']:.3f} | {one(CS, 'top3_accuracy')} | {one(CS, 'crop_accuracy')} | {one(CS, 'healthy_vs_diseased_accuracy')} | {CS['epochs_run']['mean']:.0f} | {CS['train_seconds']['mean']:.0f} s |")
w(f"| CNN, no LR decay, 100 epochs max, patience 20 (seed 42) | {one(CT, 'accuracy')} | {CT['macro_f1']['mean']:.3f} | {one(CT, 'top3_accuracy')} | {one(CT, 'crop_accuracy')} | {one(CT, 'healthy_vs_diseased_accuracy')} | {CT['epochs_run']['mean']:.0f} | {CT['train_seconds']['mean']:.0f} s |\n")
w(f"- Training accuracy only {pm(C, 'train_accuracy')} and best validation accuracy {pm(C, 'best_val_accuracy')}: the network under-fits (it does not memorise); more epochs or a smaller learning-rate decay did not change that (third row). It never reaches the 'PD36-C' level the docstring suggests ('~1.1M params' in `train.py`; measured 189,655).")
w(f"- CPU inference, batch of 1: median {C['latency_ms_median']['mean']:.0f} ms, p95 {C['latency_ms_p95']['mean']:.0f} ms per image (TensorFlow `predict`, includes Python overhead).")
w("- Best classes (seed 42): Tomato yellow-leaf-curl virus F1 0.67, Strawberry 0.38, Corn rust 0.27; many classes F1 = 0.\n")
w("### 4.3 Reference experiments (not in the product)\n")
w("| Model | Accuracy | Macro-F1 | Top-3 | Crop correct | Healthy-vs-diseased |")
w("|---|---|---|---|---|---|")
w(f"| MobileNetV2 ImageNet, head only (3 seeds) | {pm(MB, 'head_only_accuracy')} | {pm(MB, 'head_only_macro_f1', 3, False)} | - | - | - |")
w(f"| **MobileNetV2 ImageNet, head + top-30-layer fine-tune (3 seeds)** | {pm(MB, 'accuracy')} | {pm(MB, 'macro_f1', 3, False)} | {pm(MB, 'top3_accuracy')} | {pm(MB, 'crop_accuracy')} | {pm(MB, 'healthy_vs_diseased_accuracy')} |")
for k, nm in (("random_forest", "Random forest on colour/texture features (300 trees, seed 42)"), ("logistic_regression", "Logistic regression on the same features")):
    b = BL[k]
    w(f"| {nm} | {p(b['accuracy'])} | {b['macro_f1']:.3f} | {p(b['top3_accuracy'])} | {p(b['crop_accuracy'])} | {p(b['healthy_vs_diseased_accuracy'])} |")
w(f"\n- MobileNetV2 (2,293,852 parameters; {MB['train_seconds']['mean']:.0f} s training on CPU; median {MB['latency_ms_median']['mean']:.0f} ms per image) is the only model clearly above chance; healthy recall {pm(MB, 'healthy_recall')}, diseased recall {pm(MB, 'diseased_recall')}. Weakest classes (seed 42): bell pepper leaf spot, tomato bacterial spot, tomato mosaic virus (F1 0), tomato mould 0.21, blueberry 0.25.")
w("- Context: the PlantDoc authors report 29.7 % (VGG16, uncropped) and 44.5-70.5 % (cropped leaves) on a different 80/20 split; numbers are not directly comparable.\n")
w("### 4.4 Comparison with the base papers (state plainly in the documents)\n")
w("- Foliagen (base paper) generates foliage images and evaluates VGG19, ResNet50, DenseNet121, Swin and CBAM-ConvNeXt on soybean/tomato foliage; it reports up to 98 % accuracy when 5 % of a natural foliage set is added to generated data. No numbers are comparable: different task (image generation for training), crops (soybean, tomato), data (generated foliage + SHV UAV set), GPUs (2 x RTX 6000 Ada). This project did not implement Foliagen, foliage-level images or generated data.")
w("- PD36-C: 99.53 % on the New Plant Diseases Dataset (augmented PlantVillage, laboratory backgrounds, 38 classes). Here: PlantDoc field photos, 28 classes, 2,342 training images: best 50.3 %. Data difficulty, size and class set differ; do not present as a like-for-like comparison.\n")
w("## 5. Application measurements (127.0.0.1, own server, throw-away DB)\n")
dc, ds = LAT["detect_client_ms"], LAT["detect_server_ms"]
w(f"- Start-up to first `/api/health`: {LAT['startup_s']:.1f} s.")
w(f"- `POST /api/v1/detect/upload`, 100 real PlantDoc photos (median size {LAT['upload_kb']['median']:.0f} KB, p95 {LAT['upload_kb']['p95']:.0f} KB): client round trip median {dc['median']:.0f} ms, mean {dc['mean']:.0f} ms, p95 {dc['p95']:.0f} ms, max {dc['max']:.0f} ms; server-reported `processing_time_ms` median {ds['median']:.0f} ms (includes the constant +40 ms).")
for k in ("health", "diseases", "dashboard", "history", "analytics"):
    b = LAT[f"get_{k}_ms"]
    w(f"- `GET` {k}: median {b['median']:.0f} ms, p95 {b['p95']:.0f} ms (40 calls).")
w("- No concurrent-load or multi-user test was run.\n")
w("## 6. Tests\n")
w("- `scripts/smoke_test.py`: **39 / 39** API checks pass (own server on port 18416, throw-away DB).")
w(f"- `scripts/edge_tests.py`: **{EDGE['total']} checks: {EDGE['PASS']} pass, {EDGE['FAIL']} fail, {EDGE['DEFECT']} reproduce a defect of the product** (unit {EDGE['by_group']['unit']['PASS'] + EDGE['by_group']['unit']['DEFECT']} checks, API {EDGE['by_group']['api']['PASS'] + EDGE['by_group']['api']['DEFECT']} checks).")
w("- `scripts/ui_checks.py`: 55 browser checks (overflow at 360/768/1440 px, drawer, theme, language switch, filters, delete confirmation, profile save, clean console) passed at the end of the frontend session (2026-10-25); **not re-run during this documentation run** (needs both dev servers and a slow headless browser).")
w("- Defects reproduced (record in Chapter 7/8, do not hide): (1) 10 of the engine's 19 crop keys (9 of the 18 offered in the web form) crash the heuristic (HTTP 400 UNREADABLE_IMAGE); (2) top-3 scores can sum to 112 %; (3) default signing secret `agrivision-dev-secret-change-me` is public: a token forged with it is accepted unless `AGRIVISION_SECRET` is set; (4) no rate limiting on login; (5) `train.py` evaluates the test folder with 27 class names against a 28-class model, so `grape_leaf` and `grape_leaf_black_rot` labels are shifted by one (indices 25/26 instead of 26/27) and the test folder is also used for early stopping and checkpoint selection; (6) `train.py` docstring says ~1.1M parameters, the model has 189,655; (7) heuristic latency is padded by +40 ms.")
w("- Security properties verified: passwords stored as salted hashes (werkzeug scrypt), forged/expired/malformed tokens refused, other users' results return 404, upload limit 10 MB (413), extension whitelist, path traversal in file names and in /uploads/ blocked, SQL text stored as data, CORS only for localhost origins.\n")
w("## 7. API (FastAPI, `backend/main.py`)\n")
w("| Method | Path | Auth | Purpose |\n|---|---|---|---|")
for r in [("GET", "/api/health", "no", "status, class count, engine, trained_model flag"), ("GET", "/api/v1/diseases", "no", "38 knowledge-base cards"),
          ("GET", "/api/v1/diseases/{name}", "no", "one card by class or display name"), ("GET", "/api/v1/uploads/{name}", "no (random name)", "stored leaf image"),
          ("POST", "/api/v1/auth/register", "no", "create account, returns token"), ("POST", "/api/v1/auth/login", "no", "returns bearer token (7 days)"),
          ("GET", "/api/v1/auth/me", "yes", "profile"), ("PUT", "/api/v1/profile", "yes", "name, region, language en/hi/mr, crops"),
          ("GET", "/api/v1/dashboard", "yes", "totals, healthy, urgent, disease rate, 6 recent"), ("GET", "/api/v1/analytics/dashboard", "yes", "distribution, severity, timeline"),
          ("POST", "/api/v1/detect/upload", "yes", "multipart image + crop_type, returns top-3, severity, treatments"),
          ("GET", "/api/v1/history", "yes", "paged list with q, crop, disease filters"), ("GET", "/api/v1/history/export", "yes", "CSV of all scans"),
          ("GET", "/api/v1/history/{id}", "yes", "one result"), ("DELETE", "/api/v1/history/{id}", "yes", "delete result and image"),
          ("GET", "/api/v1/history/{id}/export?format=csv|pdf", "yes", "one-record CSV or PDF (reportlab)")]:
    w("| " + " | ".join(r) + " |")
w("\n## 8. Database (SQLite `agrivision/agrivision.db`)\n")
w("- `users(id PK, email UNIQUE, phone, full_name, password_hash, role='farmer', region, language='en', crops JSON text, created_at, is_active)`.")
w("- `results(id PK, user_id FK->users, image_path, image_size, predicted, confidence, top3 JSON text, severity, crop_hint, latency_ms, created_at, bookmarked)`; 12 columns, positional INSERT.")
w("- Knowledge base is Python data (`disease_db.py`), not a table. Image files are in `agrivision/static/uploads/<uuid>.<ext>`.\n")
